 "DWG se ukládá přímo v prohlížeči (vrstvy OBRYS/SKRYTE/OSY/KOTY, typy a tloušťky čar, verze AutoCAD 2000–2018+). DXF je ve formátu AutoCAD R12 pro starší a open-source programy (LibreCAD, QCAD).": "DWG wird direkt im Browser geschrieben (Layer OBRYS/SKRYTE/OSY/KOTY, Linientypen und -stärken, Versionen AutoCAD 2000–2018+). DXF liegt im Format AutoCAD R12 für ältere und Open-Source-Programme vor (LibreCAD, QCAD).",
