 "Firefox: Nastavení → Obecné → Výkon → zapněte „Použít doporučená nastavení výkonu“ (hardwarová akcelerace); v about:config musí být webgl.disabled = false. Stav ukáže about:support → Grafika.": "Firefox: Einstellungen → Allgemein → Leistung → „Empfohlene Leistungseinstellungen verwenden“ aktivieren (Hardwarebeschleunigung); in about:config muss webgl.disabled = false sein. Den Status zeigt about:support → Grafik.",
 "FKM (Viton) 75": "FKM (Viton) 75",
 "formařské analýzy jako text: podíly úkosů a podkosy, nejtenčí stěna a místo, křivost; „zobrazit“ = barevná mapa v 3D okně (pro screenshot)": "Formenbau-Analysen als Text: Anteile der Schrägen und Hinterschnitte, dünnste Wand und ihre Lage, Krümmung; „anzeigen“ = Farbkarte im 3D-Fenster (für screenshot)",
