 "Formát {0} musí být před vložením převeden (otevřete soubor znovu).": "Das Format {0} muss vor dem Einfügen umgewandelt werden (öffnen Sie die Datei erneut).",
 "Formát {0} nelze použít jako referenci – použijte STEP, BREP nebo síťový model.": "Das Format {0} kann nicht als Referenz verwendet werden – verwenden Sie STEP, BREP oder ein Netzmodell.",
