 "Ostatní (volné)": "Sonstige (Freiform)",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Jen se nezobrazí 3D model.": "Die übrigen Teile des Programms funktionieren weiter: Menüs, Hilfe, Einstellungen, Öffnen und Speichern von Dateien, 2D-Skizze und Zeichnungen. Nur das 3D-Modell wird nicht angezeigt.",
 "Ostatní části programu fungují dál: nabídky, nápověda, nastavení, otevření a uložení souborů, 2D skica i výkresy. Model se místo 3D okna zobrazuje jako zjednodušený náhled: pohledy, přizpůsobení, přiblížení, otáčení i řez fungují, výběr ploch a hran kliknutím ne – použijte seznamy ve formulářích prvků a textové příkazy.": "Die übrigen Programmteile funktionieren weiter: Menüs, Hilfe, Einstellungen, Öffnen und Speichern von Dateien, 2D-Skizze und Zeichnungen. Statt des 3D-Fensters wird das Modell als vereinfachte Vorschau angezeigt: Ansichten, Einpassen, Zoom, Drehen und Schnittansicht funktionieren, die Auswahl von Flächen und Kanten per Klick nicht – verwenden Sie die Listen in den Formularen der Elemente und Textbefehle.",
 "Osu odkazem nelze vyřešit – jádro neposkytlo odkazy.": "Die Achsreferenz kann nicht aufgelöst werden – der Kern hat keine Referenzen bereitgestellt.",
