 "Plochu {0} nelze odstranit. Odstranit lze díry, čepy, kuželová zahloubení a válcová zaoblení – rovinné plochy posuňte příkazem Vytáhnout/Zatlačit.": "Fläche {0} kann nicht entfernt werden. Entfernt werden können Bohrungen, Zapfen, Kegelsenkungen und zylindrische Verrundungen – ebene Flächen verschieben Sie mit Ziehen / Drücken.",
