 "Plochy {0} se po změně modelu nenašly podle otisku – použity původní indexy.": "Flächen {0} wurden nach der Modelländerung nicht über ihre Fingerabdrücke gefunden – die ursprünglichen Indizes werden verwendet.",
 "Plochy / hrany": "Flächen / Kanten",
 "plochý díl (rozvin) z historie ohybů – potlačením prvku se vrátí ohnutý tvar": "ebenes Teil (Abwicklung) aus der Biegehistorie – durch Unterdrücken des Features kehrt die gebogene Form zurück",
 "Plochy komponenty „{0}“ (souřadnice sestavy, {1}) – rovinné: {2}, válcové/kuželové: {3}{4}": "Flächen der Komponente „{0}“ (Baugruppenkoordinaten, {1}) – eben: {2}, zylindrisch/kegelig: {3}{4}",
 "Plochy lze místo klikání vybrat ze seznamů výše; hodnotu potvrdíte až po výběru obou ploch.": "Statt zu klicken, können die Flächen aus den Listen oben gewählt werden; den Wert bestätigen Sie erst nach der Wahl beider Flächen.",
 "Plochy lze místo klikání vybrat ze seznamů výše.": "Statt zu klicken, können die Flächen aus den Listen oben gewählt werden.",
 "Plochy lze vybrat i ze seznamu v tomto panelu; hotovou vazbu upravíte v seznamu Vazby pod stromem komponent.": "Flächen lassen sich auch aus einer Liste in diesem Panel wählen; eine fertige Verknüpfung bearbeiten Sie in der Liste Verknüpfungen unter dem Komponentenbaum.",
 "Plochy na sebe nenavazují – nejdřív je sešijte.": "Die Flächen schließen nicht aneinander an – nähen Sie sie zuerst.",
 "Plochy nejsou rovnoběžné – založena půlicí rovina.": "Die Flächen sind nicht parallel – eine Halbierungsebene wurde erstellt.",
 "Plochy netvoří jednu souvislou skořepinu – nejdřív je sešijte (Sešít plochy) nebo zvětšete toleranci.": "Die Flächen bilden keine zusammenhängende Schale – nähen Sie sie zuerst (Flächen nähen) oder erhöhen Sie die Toleranz.",
 "Plochy neuzavírají objem – {0} volných hran (chybí stěna nebo jsou mezery; zvětšete toleranci).": "Die Flächen schließen kein Volumen ein – {0} freie Kanten (eine Wand fehlt oder es gibt Lücken; erhöhen Sie die Toleranz).",
 "Plochy neuzavírají objem – chybí některá stěna nebo jsou mezery.": "Die Flächen schließen kein Volumen ein – eine Wand fehlt oder es gibt Lücken.",
 "Plochy neuzavírají objem – zkontrolujte, že na sebe navazují (Sešít plochy).": "Die Flächen schließen kein Volumen ein – prüfen Sie, ob sie aneinander anschließen (Flächen nähen).",
 "Plochy podle pravidla „{0}“: {1}": "Flächen nach Regel „{0}“: {1}",
 "Plochy se naklopí o úhel kolem průsečnice s neutrální rovinou; směr tahu určuje, na kterou stranu se úkos otevírá (u zadané roviny jen otočí její orientaci). Bez roviny i směru platí základní rovina. Dělicí křivka a stupňovitý úkos zatím nejsou k dispozici.": "Die Flächen werden um den Winkel um ihre Schnittlinie mit der neutralen Ebene geneigt; die Entformungsrichtung bestimmt, zu welcher Seite sich die Schräge öffnet (bei vorgegebener Ebene dreht sie nur deren Orientierung). Ohne Ebene und Richtung gilt die Grundebene. Trennkurve und gestufte Schräge sind noch nicht verfügbar.",
 "Plochy styčníku jsou rovnoběžné – vyberte dvě plochy svírající úhel.": "Die Knotenblechflächen sind parallel – wählen Sie zwei Flächen, die einen Winkel bilden.",
