 "Poloměr": "Radius",
 "Poloměr / velikost": "Radius / Größe",
 "Poloměr = polovina vzdálenosti rovnoběžných bočních ploch; prostřední plocha se nahradí válcem tečným k oběma. Prostřední plochu lze vynechat, je-li mezi bočními plochami jediná. Obdélníková prostřední plocha kolmá na boční se zaoblí přesně, jiná přibližně.": "Radius = halber Abstand der parallelen Seitenflächen; die Mittelfläche wird durch einen zu beiden tangentialen Zylinder ersetzt. Die Mittelfläche kann entfallen, wenn zwischen den Seitenflächen nur eine liegt. Eine rechteckige, zu den Seiten senkrechte Mittelfläche wird exakt verrundet, andere näherungsweise.",
 "poloměr = povrch, kde závit začíná: válec, nebo díra (jádro); hloubka jde do materiálu": "Radius = die Oberfläche, an der das Gewinde beginnt: Zylinder oder Bohrung (Kern); die Tiefe geht ins Material",
 "Poloměr kótovacího oblouku [mm]": "Radius des Maßbogens [mm]",
 "Poloměr kruhového profilu musí být kladný.": "Der Radius des Kreisprofils muss positiv sein.",
 "Poloměr musí být kladný.": "Der Radius muss positiv sein.",
 "Poloměr na konci R2": "Endradius R2",
 "Poloměr na začátku R1": "Anfangsradius R1",
 "Poloměr opsané": "Umkreisradius",
 "Poloměr osy": "Achsradius",
 "Poloměr se mění lineárně od začátku hrany (R1) k jejímu konci (R2). Začátek hrany určuje model – běží-li přechod obráceně, hodnoty prohoďte. Eliptické (asymetrické) zaoblení s různou vzdáleností na každé ploše jádro OCCT neumí.": "Der Radius ändert sich linear vom Kantenanfang (R1) zum Kantenende (R2). Den Kantenanfang bestimmt das Modell – läuft der Übergang verkehrt, vertauschen Sie die Werte. Elliptische (asymmetrische) Verrundungen mit unterschiedlichem Abstand je Fläche unterstützt der OCCT-Kern nicht.",
 "poloměr se po hraně mění od R1 k R2": "der Radius ändert sich entlang der Kante von R1 nach R2",
 "Poloměr šroubovice": "Helixradius",
 "Poloměr u hrany {0} musí být kladný.": "Der Radius an Kante {0} muss positiv sein.",
