 "Pracujete-li přes vzdálenou plochu (RDP), Citrix nebo ve virtuálním stroji, otevřete CAD přímo na počítači s grafickou kartou – vzdálené relace WebGL často neposkytují.": "Wenn Sie über Remotedesktop (RDP), Citrix oder in einer virtuellen Maschine arbeiten, öffnen Sie das CAD direkt auf einem Computer mit Grafikkarte – Remotesitzungen stellen WebGL oft nicht bereit.",
