 "profil (kruh, závit 60° nebo skica) tažený po šroubovici – závit, pružina, spirálová drážka": "Profil (Kreis, Gewinde 60° oder Skizze) entlang einer Helix ausgetragen – Gewinde, Feder, Spiralnut",
