 "Profil {0} L{1}": "Profil {0} L{1}",
 "Profil a dráha musí být dvě různé skici.": "Profil und Pfad müssen zwei verschiedene Skizzen sein.",
 "Profil by měl ležet v rovině kolmé na začátek dráhy (kružnice bez skici se tam umístí sama). Dráha může obsahovat úsečky, oblouky a lomené čáry – musí být souvislá. Pevná orientace = profil se po dráze jen posouvá (nenatáčí se). Vodicí křivka natáčí profil směrem k ní. Kroucení a měřítko se staví z řezů podél dráhy (hladké šablonování) – výsledek je u dlouhých drah mírně přibližný. Transformovaný přechod je určen pro hladké dráhy.": "Das Profil sollte in einer Ebene senkrecht zum Pfadanfang liegen (ein Kreis ohne Skizze wird dort automatisch platziert). Der Pfad kann Linien, Bögen und Polylinien enthalten – er muss zusammenhängend sein. Feste Ausrichtung = das Profil wird entlang des Pfads nur verschoben (nicht gedreht). Eine Leitkurve dreht das Profil zu ihr hin. Verdrehung und Maßstab werden aus Schnitten entlang des Pfads aufgebaut (glatte Ausformung) – bei langen Pfaden ist das Ergebnis leicht angenähert. Der transformierte Übergang ist für glatte Pfade gedacht.",
 "Profil je po ořezání spojů záporný – zvolte menší profil nebo jiný typ spoje.": "Das Profil ist nach dem Trimmen der Verbindungen negativ – wählen Sie ein kleineres Profil oder einen anderen Verbindungstyp.",
 "Profil je prázdný.": "Das Profil ist leer.",
 "Profil má po zkrácení nulovou délku.": "Das Profil hat nach dem Kürzen die Länge null.",
 "profil po dráze": "Profil entlang eines Pfads",
 "Profil řemene": "Riemenprofil",
 "Profil skici plochu neprotíná.": "Das Skizzenprofil schneidet die Fläche nicht.",
 "Profil U (UPN)": "U-Profil (UPN)",
 "Profil UPN {0} není v tabulce.": "Profil UPN {0} ist nicht in der Tabelle.",
 "Profil;Ks;Délka celkem [m];Hmotnost [kg]": "Profil;Stk;Gesamtlänge [m];Masse [kg]",
 "Profilová kolejnice lineárního vedení HGR": "Profilschiene der Linearführung HGR",
 "profily (jäkl, trubka, L, U, IPE…) podél úseček skici, rohy pokos/tupý": "Profile (Hohlprofil, Rohr, L, U, IPE…) entlang von Skizzenlinien, Ecken Gehrung/stumpf",
 "Profily (v pořadí)": "Profile (in Reihenfolge)",
 "Profily jsou uzavřené skici v různých rovinách (otvory se šablonují, mají-li všechny profily stejný počet). Stačí i jeden profil a bod (kužel / jehlan). Uzavřené šablonování potřebuje alespoň tři profily. Okrajové podmínky „kolmo“ / „směr“ jsou aproximace pomocným řezem v délce náběhu. Osová křivka má procházet profily (řezy se podél ní prokládají); vodicí křivka natáčí řezy směrem k sobě (použije se první). Osovou / vodicí křivku nelze kombinovat s bodem ani uzavřením.": "Profile sind geschlossene Skizzen in verschiedenen Ebenen (Löcher werden ausgeformt, wenn alle Profile gleich viele haben). Ein Profil und ein Punkt genügen (Kegel / Pyramide). Eine geschlossene Ausformung braucht mindestens drei Profile. Die Randbedingungen „senkrecht“ / „Richtung“ werden durch einen Hilfsschnitt in Anlauflänge angenähert. Die Mittellinie soll durch die Profile verlaufen (Schnitte werden entlang ihr interpoliert); eine Leitkurve dreht die Schnitte zu sich hin (die erste wird verwendet). Mittellinie / Leitkurve lassen sich nicht mit Punkt oder Schließen kombinieren.",
 "Program": "Programm",
 "Prohlížeč čtení schránky nedovoluje – vložte text do pole klávesami Ctrl+V.": "Der Browser erlaubt kein Lesen der Zwischenablage – fügen Sie den Text mit Strg+V in das Feld ein.",
 "Prohlížeč nedovolil číst schránku – vložte text do pole (Ctrl+V) a stiskněte Provést.": "Der Browser erlaubte das Lesen der Zwischenablage nicht – fügen Sie den Text in das Feld ein (Strg+V) und drücken Sie Ausführen.",
 "Prohlížeč nepodporuje kreslení do canvasu.": "Der Browser unterstützt das Zeichnen in ein Canvas nicht.",
 "prohlížeč neposkytl WebGL kontext (grafická akcelerace je vypnutá nebo nedostupná)": "der Browser hat keinen WebGL-Kontext bereitgestellt (Grafikbeschleunigung ist deaktiviert oder nicht verfügbar)",
 "Prohlížeč neposkytl WebGL, tedy hardwarově akcelerovanou grafiku, kterou 3D zobrazení potřebuje ({0}). Nejčastější příčiny: vypnutá grafická akcelerace v prohlížeči, vzdálená plocha nebo virtuální stroj bez grafické karty, zastaralý ovladač grafiky, firemní zásady prohlížeče.{1}": "Der Browser hat kein WebGL bereitgestellt, also die hardwarebeschleunigte Grafik, die die 3D-Ansicht benötigt ({0}). Häufigste Ursachen: deaktivierte Grafikbeschleunigung im Browser, Remotedesktop oder virtuelle Maschine ohne Grafikkarte, veralteter Grafiktreiber, Browser-Richtlinien des Unternehmens.{1}",
 "Prohlížeč neumí kreslit do plátna (canvas) – podklad nelze vložit.": "Der Browser kann nicht auf eine Zeichenfläche (Canvas) zeichnen – die Unterlage kann nicht eingefügt werden.",
