 "Prvek „{0}“ nelze opakovat – pole umí opakovat jen prvky s nástrojovým tělesem (vysunutí, rotace, díra, primitiva, tažení, šablonování, text), které jsou v historii před polem a nejsou potlačené.": "Das Feature „{0}“ kann nicht wiederholt werden – ein Muster wiederholt nur Features mit Werkzeugkörper (Extrusion, Rotation, Bohrung, Grundkörper, Austragung, Ausformung, Text), die in der Historie vor dem Muster liegen und nicht unterdrückt sind.",
