 "Reference má {0} ploch (síťový model) – rozdílová tělesa se nepočítala, protože by výpočet trval velmi dlouho. Objemy a mapa odchylek platí.": "Die Referenz hat {0} Flächen (Netzmodell) – Differenzkörper wurden nicht berechnet, da dies sehr lange dauern würde. Volumen und Abweichungskarte gelten.",
