 "Rovina rozdělí těleso „{0}“ na dvě: strana ve směru normály zůstane tímto tělesem, opačná strana je nové těleso. Další prvky pracují s tělesem, které vyberete v poli Těleso nebo ve správci.": "Die Ebene teilt den Körper „{0}“ in zwei: die Seite in Normalenrichtung bleibt dieser Körper, die Gegenseite ist ein neuer Körper. Folgende Elemente arbeiten an dem Körper, den Sie im Feld Körper oder im Manager wählen.",
