 "Výsledek je prázdný.": "Das Ergebnis ist leer.",
 "Výsledek má neplatnou geometrii (sebeprotínající nebo neorientovatelné plochy) – export STEP může selhat. Změňte parametry: profil nesmí být tečný k povrchu tělesa, dráha se nesmí protínat.": "Das Ergebnis hat eine ungültige Geometrie (selbstschneidende oder nicht orientierbare Flächen) – der STEP-Export kann fehlschlagen. Ändern Sie die Parameter: das Profil darf nicht tangential zur Körperoberfläche sein, der Pfad darf sich nicht selbst schneiden.",
