 "značka: za pohledem zadejte bod – pohled přední v x y (mm modelu v rovině pohledu)": "Symbol: nach der Ansicht einen Punkt angeben – ansicht vorne bei x y (Modell-mm in der Ansichtsebene)",
 "značky jako nástroje výkresu: cíl „na <kóta>“ (popisek nebo id a3) nebo „pohled přední v x y“ (mm modelu v rovině pohledu, přichytí se ke geometrii); text v mm listu od levého dolního rohu": "Symbole wie die Zeichenwerkzeuge: Ziel „an <maß>“ (Beschriftung oder Id a3) oder „ansicht vorne bei x y“ (Modell-mm in der Ansichtsebene, an Geometrie gefangen); Text in Blatt-mm von der linken unteren Ecke",
